; ============================================================
; Bank $D0: the data the code source does not emit
;
; Generated by tools/extract_data.py from symbols/data_survey.csv;
; do not edit (run `python3 tools/extract_data.py generate`). Each
; piece is a row of the survey (its kind, format, readers and
; confidence are there) at its address. fill and pointer tables are
; source; incbin reads an asset that tools/extract_data.py writes
; from your own ROM to build/assets/, a pack tools/build_rom.py
; makes from one in build/packs/ (event scripts assembled from
; their disassembly first), text or records it encodes into
; build/text/ and build/records/, battle and layer-effect
; scripts it assembles into build/battle/ and build/fx/, or
; graphics it encodes from images into build/gfx/
; (symbols/data_assets.csv lists them; nothing here is ROM data).
; ============================================================

; $D0:0000-$D0:DEBF (57,024 B), graphics, confirmed: action graphics source tiles (2bpp, some
; with a third plane)
; Read by BattleCD_Tile4Copy, BattleCD_Tile4Planes.
org $D00000
BattleRom_FxGfxSrc:
    incbin "../../build/assets/graphics/BattleRom_FxGfxSrc.bin"

; $D0:DEC0-$D0:DFFF (320 B), padding, probable: 320 x $FF
org $D0DEC0
Padding_D0DEC0:
    fillbyte $FF
    fill 320

; $D0:E000-$D0:E011 (18 B), table, confirmed: 3 B per background set: long pointer to its packed
; map
; Read by BattleFx_LoadBgSet.
org $D0E000
BattleRom_BgMapPtrs:
    dl BattleBgMapPack_000                ; 0
    dl BattleBgMapPack_001                ; 1
    dl BattleBgMapPack_002                ; 2
    dl BattleBgMapPack_003                ; 3
    dl BattleBgMapPack_004                ; 4
    dl BattleBgMapPack_005                ; 5

; $D0:E012-$D0:E277 (614 B), packed_lz, confirmed: lz11 -> 2048 B: battle background tile map
; Read by BattleFx_LoadBgSet.
org $D0E012
BattleBgMapPack_000:
    incbin "../../build/packs/BattleBgMapPack_000.lz"          ; lz11 -> 2048 B

; $D0:E278-$D0:E577 (768 B), packed_lz, confirmed: lz11 -> 2048 B: battle background tile map
; Read by BattleFx_LoadBgSet.
org $D0E278
BattleBgMapPack_001:
    incbin "../../build/packs/BattleBgMapPack_001.lz"          ; lz11 -> 2048 B

; $D0:E578-$D0:EAFF (1,416 B), packed_lz, confirmed: lz11 -> 2048 B: battle background tile map
; Read by BattleFx_LoadBgSet.
org $D0E578
BattleBgMapPack_002:
    incbin "../../build/packs/BattleBgMapPack_002.lz"          ; lz11 -> 2048 B

; $D0:EB00-$D0:ED8A (651 B), packed_lz, confirmed: lz11 -> 2048 B: battle background tile map
; Read by BattleFx_LoadBgSet.
org $D0EB00
BattleBgMapPack_003:
    incbin "../../build/packs/BattleBgMapPack_003.lz"          ; lz11 -> 2048 B

; $D0:ED8B-$D0:F197 (1,037 B), packed_lz, confirmed: lz11 -> 2048 B: battle background tile map
; Read by BattleFx_LoadBgSet.
org $D0ED8B
BattleBgMapPack_004:
    incbin "../../build/packs/BattleBgMapPack_004.lz"          ; lz11 -> 2048 B

; $D0:F198-$D0:F98E (2,039 B), packed_lz, confirmed: lz11 -> 2048 B: battle background tile map
; Read by BattleFx_LoadBgSet.
org $D0F198
BattleBgMapPack_005:
    incbin "../../build/packs/BattleBgMapPack_005.lz"          ; lz11 -> 2048 B

; $D0:F98F-$D0:F9FF (113 B), padding, confirmed: 113 x $00
org $D0F98F
Padding_D0F98F:
    fillbyte $00
    fill 113

; $D0:FA00-$D0:FBE1 (482 B), palette, confirmed: background sets' palette rows
; (BattleFx_BgSetPalOfs gives the offsets)
; Read by BattleFx_LoadBgSet.
org $D0FA00
BattleRom_BgSetPalettes:
    incbin "../../build/assets/palette/BattleRom_BgSetPalettes.bin"

; $D0:FBE2-$D0:FCFF (286 B), palette, confirmed: 9 sets of 14 colours, $20 apart
; Read by BattleFx_FindGradStart, BattleFx_HpGradientTick.
org $D0FBE2
BattleRom_GradColours:
    incbin "../../build/assets/palette/BattleRom_GradColours.bin"

; $D0:FD00-$D0:FD5F (96 B), palette, confirmed: 48 colours (BGR555)
; Read by BattleFx_LoadBgRows2To4.
org $D0FD00
Palette_D0FD00:
    incbin "../../build/records/Palette_D0FD00.bin"          ; records: palette 48 x 2 B

; $D0:FD60-$D0:FFFF (672 B), padding, confirmed: 672 x $FF
org $D0FD60
Padding_D0FD60:
    fillbyte $FF
    fill 672
